import{_ as e,C as a,c as o,o as i,j as r,b as t,a0 as s,a as l,w as n,G as c,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Exercícios de treinamento","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/training/drills.md","filePath":"pt/education/training/drills.md"}');const m=e({name:"pt/education/training/drills.md"},[["render",function(e,u,m,p,h,g){const b=a("Mermaid");return i(),o("div",null,[u[1]||(u[1]=r("h1",{id:"exercicios-de-treinamento",tabindex:"-1"},[l("Exercícios de treinamento "),r("a",{class:"header-anchor",href:"#exercicios-de-treinamento","aria-label":'Permalink to "Exercícios de treinamento"'},"​")],-1)),u[2]||(u[2]=r("p",null,"Aqui estão exercícios comprovados usados por jogadores de elite. Cada exercício tem um propósito específico - escolha com base no que você precisa desenvolver.",-1)),u[3]||(u[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"A Grande Ideia"),r("p",null,[r("strong",null,"Cada exercício tem um propósito específico."),l(" Não jogue as bolas aleatoriamente — escolha exercícios que visem suas fraquezas e apoiem seus objetivos. Acompanhe seu progresso para ver a melhora.")])],-1)),(i(),t(d,null,{default:n(()=>[c(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BExerc%C3%ADcios%20de%20treinamento%5D%20--%3E%20B%5BExerc%C3%ADcios%20de%20apontamento%5D%0A%20%20%20%20A%20--%3E%20C%5BTreinos%20de%20chute%5D%0A%20%20%20%20A%20--%3E%20D%5BExerc%C3%ADcios%20Mentais%5D%0A%20%20%20%20A%20--%3E%20E%5BSimula%C3%A7%C3%A3o%20de%20Jogo%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BPrecis%C3%A3o%5D%0A%20%20%20%20B%20--%3E%20G%5BControle%20de%20Dist%C3%A2ncia%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BTaxa%20de%20acerto%5D%0A%20%20%20%20C%20--%3E%20I%5BTiro%20sob%20press%C3%A3o%5D%0A%0A%20%20%20%20D%20--%3E%20J%5BPr%C3%A1tica%20de%20rotina%5D%0A%20%20%20%20D%20--%3E%20K%5BVisualiza%C3%A7%C3%A3o%5D%0A%0A%20%20%20%20E%20--%3E%20L%5BPrepara%C3%A7%C3%A3o%20para%20a%20competi%C3%A7%C3%A3o%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...u[0]||(u[0]=[l(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=s('<h2 id="exercicios-de-apontamento" tabindex="-1">Exercícios de apontamento <a class="header-anchor" href="#exercicios-de-apontamento" aria-label="Permalink to &quot;Exercícios de apontamento&quot;">​</a></h2><h3 id="o-beco" tabindex="-1">O Beco <a class="header-anchor" href="#o-beco" aria-label="Permalink to &quot;O Beco&quot;">​</a></h3><p><strong>Objetivo:</strong> Isolar o ângulo de liberação e a consistência da linha.</p><p><strong>Configurar:</strong></p><ul><li>Coloque dois marcadores a 30-40 cm de distância um do outro, a cerca de 1 metro do círculo.</li><li>O alvo está a 7-9 metros de distância.</li></ul><p><strong>Furar:</strong></p><ul><li>Arremesse pelo &quot;corredor&quot; (entre os marcadores)</li><li>Qualquer arremesso que atinja um marcador é considerado &quot;morto&quot;.</li><li>Foque em um ponto de liberação consistente.</li></ul><p><strong>Progressão:</strong></p><ul><li>Estreite o beco à medida que você melhora.</li><li>Varie a distância do alvo</li><li>Adicionar uma zona de aterrissagem específica</li></ul><h3 id="zonas-de-precisao" tabindex="-1">Zonas de Precisão <a class="header-anchor" href="#zonas-de-precisao" aria-label="Permalink to &quot;Zonas de Precisão&quot;">​</a></h3><p><strong>Objetivo:</strong> Desenvolver a precisão em áreas específicas.</p><p><strong>Configurar:</strong></p><ul><li>Delimite zonas em torno de um alvo (por exemplo, círculos a 20 cm, 40 cm, 60 cm).</li><li>Ou utilize marcadores naturais no terreno.</li></ul><p><strong>Pontuação:</strong></p><ul><li>Dentro de 20 cm: 3 pontos</li><li>Dentro de 40 cm: 2 pontos</li><li>Dentro de 60 cm: 1 ponto</li><li>Exterior: 0 pontos</li></ul><p><strong>Furar:</strong></p><ul><li>Lance 10 bolas e anote sua pontuação.</li><li>Objetivo: Melhoria consistente ao longo das sessões</li></ul><h3 id="variacao-de-distancia" tabindex="-1">Variação de distância <a class="header-anchor" href="#variacao-de-distancia" aria-label="Permalink to &quot;Variação de distância&quot;">​</a></h3><p><strong>Objetivo:</strong> Desenvolver o controle de profundidade</p><p><strong>Configurar:</strong></p><ul><li>Coloque alvos a 6m, 7m, 8m, 9m e 10m.</li></ul><p><strong>Furar:</strong></p><ul><li>Arremesse para cada distância em ordem aleatória.</li><li>O parceiro indica a distância.</li><li>Concentre-se em ajustar o peso, não a técnica.</li></ul><p><strong>Variação:</strong></p><ul><li>Adicione chamadas &quot;curtas&quot; e &quot;longas&quot; após liberar.</li><li>É preciso ajustar durante o voo (desenvolve a sensibilidade).</li></ul><h2 id="treinos-de-chute" tabindex="-1">Treinos de chute <a class="header-anchor" href="#treinos-de-chute" aria-label="Permalink to &quot;Treinos de chute&quot;">​</a></h2><h3 id="a-escada-de-tiro" tabindex="-1">A Escada de Tiro <a class="header-anchor" href="#a-escada-de-tiro" aria-label="Permalink to &quot;A Escada de Tiro&quot;">​</a></h3><p><strong>Objetivo:</strong> Desenvolver a precisão sob pressão progressiva</p><p><strong>Configurar:</strong></p><ul><li>Coloque uma bola alvo a 6 metros.</li><li>Marque distâncias em 7m, 8m, 9m, 10m</li></ul><p><strong>Furar:</strong></p><ul><li>Comece em 6 metros</li><li>Golpe = recue um metro</li><li>Erro = avançar um metro (ou reiniciar)</li><li>Objetivo: Alcançar 10 metros</li></ul><p><strong>Variações:</strong></p><ul><li>Versão rigorosa: Qualquer erro retorna a 6m</li><li>Versão cronometrada: Até onde você consegue chegar em 10 minutos?</li><li>Versão em equipe: Alternar com o parceiro</li></ul><h3 id="a-barreira-blox" tabindex="-1">A Barreira (Blox) <a class="header-anchor" href="#a-barreira-blox" aria-label="Permalink to &quot;A Barreira (Blox)&quot;">​</a></h3><p><strong>Objetivo:</strong> Forçar disparos em arco alto</p><p><strong>Configurar:</strong></p><ul><li>Coloque uma barreira (vara, barbante ou obstáculo) entre você e o alvo.</li><li>A barreira deve ser alta o suficiente para exigir um passe por cima da defesa.</li></ul><p><strong>Furar:</strong></p><ul><li>É preciso ultrapassar a barreira para atingir o alvo.</li><li>Qualquer arremesso que atinja a barreira é considerado &quot;inválido&quot;.</li><li>Desenvolve um ponto de liberação elevado</li></ul><p><strong>Por que isso é importante:</strong></p><ul><li>A competição muitas vezes exige tiro sobre obstáculos.</li><li>Aumenta a versatilidade nos seus disparos.</li></ul><h3 id="pista-de-obstaculos" tabindex="-1">Pista de Obstáculos <a class="header-anchor" href="#pista-de-obstaculos" aria-label="Permalink to &quot;Pista de Obstáculos&quot;">​</a></h3><p><strong>Objetivo:</strong> Desenvolver a técnica de filmagem a partir de diferentes ângulos.</p><p><strong>Configurar:</strong></p><ul><li>Coloque a bola alvo no centro.</li><li>Adicione obstáculos (outras bolas, marcadores) ao redor.</li></ul><p><strong>Furar:</strong></p><ul><li>Fotografe de diferentes posições ao redor do círculo.</li><li>É preciso encontrar o ângulo que funcione.</li><li>Desenvolve a leitura das linhas de tiro.</li></ul><h2 id="exercicios-de-treinamento-mental" tabindex="-1">Exercícios de Treinamento Mental <a class="header-anchor" href="#exercicios-de-treinamento-mental" aria-label="Permalink to &quot;Exercícios de Treinamento Mental&quot;">​</a></h2><h3 id="repeticao-de-rotina" tabindex="-1">Repetição de rotina <a class="header-anchor" href="#repeticao-de-rotina" aria-label="Permalink to &quot;Repetição de rotina&quot;">​</a></h3><p><strong>Objetivo:</strong> Automatizar sua rotina pré-injeção</p><p><strong>Furar:</strong></p><ul><li>Pratique sua rotina completa sem arremessar</li><li>Analise cada etapa cuidadosamente.</li><li>Faça de 10 a 20 repetições.</li><li>Em seguida, adicione o arremesso.</li></ul><p><strong>Foco:</strong></p><ul><li>Cronometragem consistente</li><li>Transição clara do pensamento à execução.</li><li>A mesma rotina sempre.</li></ul><h3 id="pontos-de-pressao" tabindex="-1">Pontos de pressão <a class="header-anchor" href="#pontos-de-pressao" aria-label="Permalink to &quot;Pontos de pressão&quot;">​</a></h3><p><strong>Objetivo:</strong> Praticar o desempenho sob pressão</p><p><strong>Configurar:</strong></p><ul><li>Crie um cenário &quot;obrigatório&quot;</li><li>Estabelecer consequências para o não comparecimento.</li></ul><p><strong>Exemplos:</strong></p><ul><li>&quot;Faça 3 em linha ou comece de novo&quot;</li><li>&quot;Erre e faça 10 flexões&quot;</li><li>&quot;Anuncie seu alvo antes de arremessar&quot;</li></ul><p><strong>Chave:</strong></p><ul><li>A pressão deve ser sentida como real.</li><li>Pratique sua resposta mental à pressão.</li><li>Use sua rotina exatamente como na competição.</li></ul><h3 id="pratica-de-recuperacao" tabindex="-1">Prática de recuperação <a class="header-anchor" href="#pratica-de-recuperacao" aria-label="Permalink to &quot;Prática de recuperação&quot;">​</a></h3><p><strong>Objetivo:</strong> Desenvolver o hábito de reiniciar a mente rapidamente</p><p><strong>Furar:</strong></p><ul><li>Lançar intencionalmente uma bola ruim</li><li>Pratique imediatamente o SOAS (Parar, Observar, Aceitar, Deslizar).</li><li>Lance a próxima bola com total empenho.</li></ul><p><strong>Foco:</strong></p><ul><li>Não se prenda ao erro.</li><li>Reinicie completamente antes do próximo lançamento.</li><li>Mantenha uma linguagem corporal positiva.</li></ul><h2 id="exercicios-de-simulacao-de-jogos" tabindex="-1">Exercícios de simulação de jogos <a class="header-anchor" href="#exercicios-de-simulacao-de-jogos" aria-label="Permalink to &quot;Exercícios de simulação de jogos&quot;">​</a></h2><h3 id="o-deleite-de-millieu" tabindex="-1">O deleite de Millieu <a class="header-anchor" href="#o-deleite-de-millieu" aria-label="Permalink to &quot;O deleite de Millieu&quot;">​</a></h3><p><strong>Objetivo:</strong> Quebrar a rigidez rítmica, desenvolver versatilidade</p><p><strong>Furar:</strong></p><ul><li>Alterne entre apontar e atirar a cada arremesso.</li><li>Não podem ocorrer dois lançamentos consecutivos do mesmo tipo.</li><li>Desenvolve a capacidade de alternar entre modos.</li></ul><h3 id="jogo-de-cenario" tabindex="-1">Jogo de Cenário <a class="header-anchor" href="#jogo-de-cenario" aria-label="Permalink to &quot;Jogo de Cenário&quot;">​</a></h3><p><strong>Objetivo:</strong> Praticar a tomada de decisões táticas</p><p><strong>Configurar:</strong></p><ul><li>Crie situações de jogo realistas</li><li>Atribua pontuações e contagens de bolas.</li></ul><p><strong>Exemplos:</strong></p><ul><li>&quot;Você está perdendo por 10 a 8, seu oponente tem 2 pontos e você tem 2 bolas.&quot;</li><li>&quot;Empate de 6 a 6, você tem a última bola, eles têm 1 ponto&quot;</li></ul><p><strong>Furar:</strong></p><ul><li>Decida o que fazer</li><li>Executar com total comprometimento</li><li>Reavalie a decisão posteriormente.</li></ul><h3 id="jogo-de-partida-com-regras" tabindex="-1">Jogo de Partida com Regras <a class="header-anchor" href="#jogo-de-partida-com-regras" aria-label="Permalink to &quot;Jogo de Partida com Regras&quot;">​</a></h3><p><strong>Objetivo:</strong> Simulação de competição</p><p><strong>Variações:</strong></p><ul><li>Jogar até 13 (jogo completo)</li><li>Jogar até 7 (menos partidas, mais jogos)</li><li>&quot;Pontos de pressão&quot; - certas extremidades valem o dobro</li><li>&quot;Morte súbita&quot; - quem perder um end primeiro perde o jogo.</li></ul><h2 id="acompanhando-seus-exercicios" tabindex="-1">Acompanhando seus exercícios <a class="header-anchor" href="#acompanhando-seus-exercicios" aria-label="Permalink to &quot;Acompanhando seus exercícios&quot;">​</a></h2><p>Mantenha um registro para cada exercício:</p><table tabindex="0"><thead><tr><th>Data</th><th>Furar</th><th>Pontuação/Resultado</th><th>Notas</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Acompanhamento ao longo do tempo:</strong></p><ul><li>Você está melhorando?</li><li>Quais exercícios são mais úteis?</li><li>Onde você encontra dificuldades?</li></ul><h2 id="como-criar-uma-sessao-de-treinamento" tabindex="-1">Como criar uma sessão de treinamento <a class="header-anchor" href="#como-criar-uma-sessao-de-treinamento" aria-label="Permalink to &quot;Como criar uma sessão de treinamento&quot;">​</a></h2><h3 id="aquecimento-10-min" tabindex="-1">Aquecimento (10 min) <a class="header-anchor" href="#aquecimento-10-min" aria-label="Permalink to &quot;Aquecimento (10 min)&quot;">​</a></h3><ul><li>Arremessos fáceis para soltar o corpo</li><li>Sem pressão, apenas sinta</li></ul><h3 id="foco-tecnico-20-30-min" tabindex="-1">Foco técnico (20-30 min) <a class="header-anchor" href="#foco-tecnico-20-30-min" aria-label="Permalink to &quot;Foco técnico (20-30 min)&quot;">​</a></h3><ul><li>Um ou dois exercícios focados em habilidades específicas</li><li>Prática em blocos para o desenvolvimento de novas habilidades</li><li>Prática aleatória para habilidades já estabelecidas</li></ul><h3 id="simulacao-de-pressao-jogo-20-30-min" tabindex="-1">Simulação de pressão/jogo (20-30 min) <a class="header-anchor" href="#simulacao-de-pressao-jogo-20-30-min" aria-label="Permalink to &quot;Simulação de pressão/jogo (20-30 min)&quot;">​</a></h3><ul><li>Adicionar consequências</li><li>Criar cenários realistas</li><li>Pratique habilidades mentais</li></ul><h3 id="resfriamento-10-min" tabindex="-1">Resfriamento (10 min) <a class="header-anchor" href="#resfriamento-10-min" aria-label="Permalink to &quot;Resfriamento (10 min)&quot;">​</a></h3><ul><li>Lançamentos fáceis</li><li>Reflita sobre a sessão.</li><li>Anote em que trabalhar a seguir.</li></ul><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Furadeiras são ferramentas. Escolha a ferramenta certa para o que você precisa construir.</p></blockquote><p>Não se limite a lançar bolas aleatoriamente. Treine com propósito.</p>',103))])}]]);export{u as __pageData,m as default};
